mapper.select:
SELECT t.stock_code AS ticker, t.base_date AS base_date, t.close_price AS close_krw
FROM (
    SELECT p.stock_code, p.base_date, p.close_price,
           ROW_NUMBER() OVER (PARTITION BY p.stock_code ORDER BY p.base_date DESC) AS rn
    FROM domestic_base_price p
    WHERE p.stock_code IN

        #{ticker}

      AND p.base_date <= #{asOf}
      AND p.base_date > #{fromDate}
      AND p.close_price IS NOT NULL AND p.close_price > 0
) t
WHERE t.rn <= #{days}
ORDER BY t.stock_code, t.base_date
